        val = act.get("value")
        if op == "begin":
            tx = conn
            tx_buffer = {}
        elif op == "commit":
            if tx == conn:
                for k, v in tx_buffer.items():
                    if v is None:
                        committed.pop(k, None)
                    else:
                        committed[k] = v
                tx = None
                tx_buffer = {}
        elif op == "rollback":
            if tx == conn:
                tx = None
                tx_buffer = {}
        elif op == "put":
            if tx == conn:
                if key in tx_buffer:
                    if tx_buffer[key] is not None:
                        main_changes = 0
                    else:
                        tx_buffer[key] = val
                        main_changes = 1
                elif key in committed:
                    main_changes = 0
                else:
                    tx_buffer[key] = val
                    main_changes = 1
